import test from "node:test";
import assert from "node:assert/strict";
import { deepGet } from "./solution.mjs";
const obj = { a: { b: [{ c: "x" }] } };

test("nested path with numeric index", () => assert.equal(deepGet(obj, "a.b.0.c"), "x"));
test("missing path", () => assert.equal(deepGet(obj, "a.b.0.z"), undefined));
test("missing root segment", () => assert.equal(deepGet(obj, "x.y"), undefined));
